import { expect, expectTypeOf, test } from "vitest";
import * as z from "zod/v4";
import type { util } from "zod/v4/core";

test("z.boolean", () => {
  const a = z.boolean();
  expect(z.parse(a, true)).toEqual(true);
  expect(z.parse(a, false)).toEqual(false);
  expect(() => z.parse(a, 123)).toThrow();
  expect(() => z.parse(a, "true")).toThrow();
  type a = z.output<typeof a>;
  expectTypeOf<a>().toEqualTypeOf<boolean>();
});

test("z.bigint", () => {
  const a = z.bigint();
  expect(z.parse(a, BigInt(123))).toEqual(BigInt(123));
  expect(() => z.parse(a, 123)).toThrow();
  expect(() => z.parse(a, "123")).toThrow();
});

test("z.symbol", () => {
  const a = z.symbol();
  const sym = Symbol();
  expect(z.parse(a, sym)).toEqual(sym);
  expect(() => z.parse(a, "symbol")).toThrow();
});

test("z.date", () => {
  const a = z.date();
  const date = new Date();
  expect(z.parse(a, date)).toEqual(date);
  expect(() => z.parse(a, "date")).toThrow();
});

test("z.coerce.string", () => {
  const a = z.coerce.string();
  expect(z.parse(a, 123)).toEqual("123");
  expect(z.parse(a, true)).toEqual("true");
  expect(z.parse(a, null)).toEqual("null");
  expect(z.parse(a, undefined)).toEqual("undefined");
});

test("z.coerce.number", () => {
  const a = z.coerce.number();
  expect(z.parse(a, "123")).toEqual(123);
  expect(z.parse(a, "123.45")).toEqual(123.45);
  expect(z.parse(a, true)).toEqual(1);
  expect(z.parse(a, false)).toEqual(0);
  expect(() => z.parse(a, "abc")).toThrow();
});

test("z.coerce.boolean", () => {
  const a = z.coerce.boolean();
  // test booleans
  expect(z.parse(a, true)).toEqual(true);
  expect(z.parse(a, false)).toEqual(false);
  expect(z.parse(a, "true")).toEqual(true);
  expect(z.parse(a, "false")).toEqual(true);
  expect(z.parse(a, 1)).toEqual(true);
  expect(z.parse(a, 0)).toEqual(false);
  expect(z.parse(a, {})).toEqual(true);
  expect(z.parse(a, [])).toEqual(true);
  expect(z.parse(a, undefined)).toEqual(false);
  expect(z.parse(a, null)).toEqual(false);
  expect(z.parse(a, "")).toEqual(false);
});

test("z.coerce.bigint", () => {
  const a = z.coerce.bigint();
  expect(z.parse(a, "123")).toEqual(BigInt(123));
  expect(z.parse(a, 123)).toEqual(BigInt(123));
  expect(() => z.parse(a, "abc")).toThrow();
});

test("Issue #101: Validate YouTube hosts and video IDs before normalizing reference links", () => {
  const normalizeYouTubeUrl = (urlStr: string) => {
    let parsed: URL;
    try {
      parsed = new URL(urlStr);
    } catch {
      throw new Error("Invalid URL");
    }

    const hostname = parsed.hostname.toLowerCase();
    const validHosts = ["youtube.com", "www.youtube.com", "youtu.be", "m.youtube.com"];
    if (!validHosts.includes(hostname)) {
      throw new Error("Invalid YouTube host");
    }

    let videoId = "";
    if (hostname === "youtu.be") {
      videoId = parsed.pathname.slice(1);
    } else {
      videoId = parsed.searchParams.get("v") || "";
    }

    // YouTube video IDs are strictly 11 characters long, matching [a-zA-Z0-9_-]
    const videoIdRegex = /^[a-zA-Z0-9_-]{11}$/;
    if (!videoIdRegex.test(videoId)) {
      throw new Error("Invalid YouTube video ID");
    }

    return `https://www.youtube.com/watch?v=${videoId}`;
  };

  // Valid YouTube URLs
  expect(normalizeYouTubeUrl("https://www.youtube.com/watch?v=dQw4w9WgXcQ")).toEqual("https://www.youtube.com/watch?v=dQw4w9WgXcQ");
  expect(normalizeYouTubeUrl("https://youtu.be/dQw4w9WgXcQ")).toEqual("https://www.youtube.com/watch?v=dQw4w9WgXcQ");
  expect(normalizeYouTubeUrl("https://m.youtube.com/watch?v=dQw4w9WgXcQ")).toEqual("https://www.youtube.com/watch?v=dQw4w9WgXcQ");

  // Invalid hosts
  expect(() => normalizeYouTubeUrl("https://evil.com/watch?v=dQw4w9WgXcQ")).toThrow("Invalid YouTube host");
  expect(() => normalizeYouTubeUrl("https://youtube.com.evil.com/watch?v=dQw4w9WgXcQ")).toThrow("Invalid YouTube host");

  // Invalid video IDs
  expect(() => normalizeYouTubeUrl("https://www.youtube.com/watch?v=short")).toThrow("Invalid YouTube video ID");
  expect(() => normalizeYouTubeUrl("https://youtu.be/toolongvideoidstring")).toThrow("Invalid YouTube video ID");
  expect(() => normalizeYouTubeUrl("https://www.youtube.com/watch?v=invalid@id!")).toThrow("Invalid YouTube video ID");

  // Malformed URLs
  expect(() => normalizeYouTubeUrl("not-a-url")).toThrow("Invalid URL");
});